import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_note(name: str) -> str:
    """Return the UTF-8 text of the file `name` inside the `notes` directory.

    `notes` is resolved relative to the current working directory, and `name`
    comes from an untrusted request. Nested names such as "sub/a.txt" are
    allowed, but only if the fully resolved path (after following `..`,
    absolute paths, and symlinks) is still inside `notes`.

    Returns "" if the file is missing, is not a regular file, cannot be read
    or decoded, the name is empty or invalid (e.g. contains a NUL byte), or
    the name would reach anything outside `notes`. Never raises.
    """
    if not name or "\x00" in name:
        return ""
    try:
        if name.startswith(("/", "\\")):
            return ""
        given = Path(name)
        if given.is_absolute() or given.drive:
            return ""
        base = Path(NOTES_DIR).resolve()
        target = (base / given).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "sub").mkdir()
    (notes / "sub" / "b.txt").write_text("nested", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("evil", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_file(sandbox: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_nested_file(sandbox: Path) -> None:
    assert read_note("sub/b.txt") == "nested"


def test_dotdot_that_stays_inside(sandbox: Path) -> None:
    assert read_note("sub/../a.txt") == "hello"


def test_unicode_content(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "u.txt").write_text("héllo ☃", encoding="utf-8")
    assert read_note("u.txt") == "héllo ☃"


def test_missing_file(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name(sandbox: Path) -> None:
    assert read_note("") == ""


def test_directory_name(sandbox: Path) -> None:
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_undecodable_file(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\xff")
    assert read_note("bin.dat") == ""


def test_null_byte(sandbox: Path) -> None:
    assert read_note("a.txt\x00") == ""
    assert read_note("\x00") == ""


@pytest.mark.parametrize(
    "name",
    [
        "../secret.txt",
        "../../secret.txt",
        "sub/../../secret.txt",
        "notes/../secret.txt",
        "./../secret.txt",
        "..",
        "../",
        "..\\secret.txt",
        "../notes_evil/x.txt",
        "../notes/../secret.txt",
        "sub/../../notes_evil/x.txt",
    ],
)
def test_traversal_rejected(sandbox: Path, name: str) -> None:
    assert read_note(name) == ""


def test_absolute_path_rejected(sandbox: Path) -> None:
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note(str(sandbox / NOTES_DIR / "a.txt")) == ""
    assert read_note("/etc/passwd") == ""


def test_absolute_path_with_double_slash(sandbox: Path) -> None:
    assert read_note("//" + str(sandbox / "secret.txt")) == ""


def test_symlink_file_escaping_rejected(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        os.symlink(sandbox / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlink_dir_escaping_rejected(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "linkdir"
    try:
        os.symlink(sandbox, link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("linkdir/secret.txt") == ""


def test_symlink_inside_notes_allowed(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "alias.txt"
    try:
        os.symlink(sandbox / NOTES_DIR / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "hello"


def test_unreadable_file(sandbox: Path) -> None:
    p = sandbox / NOTES_DIR / "locked.txt"
    p.write_text("x", encoding="utf-8")
    p.chmod(0)
    try:
        if os.access(p, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_missing_notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""
